import{_ as a,a as s,b as t,c as i,d as n,e as r}from"./chunks/web-panel-016-177.COntiTnq.js";import{_ as o}from"./chunks/projects-sidebar-manager.1CSA31F-.js";import{_ as l,o as d,c,a3 as p}from"./chunks/framework.BlfGB29P.js";const E=JSON.parse('{"title":"Sidebar Manager","description":"Folders, colors, opacity and links in the Home Assistant sidebar. Version 0.1.11, DE/EN/FR.","frontmatter":{"title":"Sidebar Manager","description":"Folders, colors, opacity and links in the Home Assistant sidebar. Version 0.1.11, DE/EN/FR."},"headers":[],"relativePath":"en/projects/sidebar-manager/index.md","filePath":"en/projects/sidebar-manager/index.md","lastUpdated":1794511932000}'),h={name:"en/projects/sidebar-manager/index.md"};function g(m,e,u,b,k,f){return d(),c("div",null,[...e[0]||(e[0]=[p('<h1 id="sidebar-manager" tabindex="-1">Sidebar Manager <a class="header-anchor" href="#sidebar-manager" aria-label="Permalink to &quot;Sidebar Manager&quot;">​</a></h1><h2 id="new-in-0-1-11-aligned-sidebar-icons" tabindex="-1">New in 0.1.11: Aligned sidebar icons <a class="header-anchor" href="#new-in-0-1-11-aligned-sidebar-icons" aria-label="Permalink to &quot;New in 0.1.11: Aligned sidebar icons&quot;">​</a></h2><p>Group and custom-link icons now measure 24 × 24 px. In the collapsed sidebar, they share the same horizontal center as native Home Assistant icons.</p><p>Verified on .177 with Home Assistant 2026.11.0 on 11 November 2026. Group icons align with the Overview icon in both sidebar layouts. The Logs, Automations, and States link icons are centered in the collapsed sidebar. The user test also passed.</p><h2 id="new-in-0-1-10-home-assistant-shortcuts" tabindex="-1">New in 0.1.10: Home Assistant shortcuts <a class="header-anchor" href="#new-in-0-1-10-home-assistant-shortcuts" aria-label="Permalink to &quot;New in 0.1.10: Home Assistant shortcuts&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Marketplace requires Home Assistant 2026.11.0</p><p><strong>The Marketplace shortcut is offered only on HA 2026.11.0 or newer.</strong> It is hidden on older or unknown versions. The package minimum remains <strong>HA 2026.10.3</strong>; other presets are independent of this requirement. The link does not install Marketplace or grant additional permissions.</p></div><p>Open <strong>Edit sidebar → Manage groups and links → Home Assistant shortcuts</strong>, choose a folder and click <strong>Add</strong>. The section uses two columns on desktop and one on narrow screens.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Shortcut</th><th>Default icon</th><th>Target</th></tr></thead><tbody><tr><td>Logs</td><td><code>mdi:history</code></td><td><code>/config/logs</code></td></tr><tr><td>Automations</td><td><code>mdi:robot</code></td><td><code>/config/automation/dashboard</code></td></tr><tr><td>Entities</td><td><code>mdi:shape</code></td><td><code>/config/entities</code></td></tr><tr><td><strong>Marketplace · HA 2026.11.0+</strong></td><td><code>mdi:store</code></td><td><code>/marketplace/browse?group=status</code></td></tr><tr><td>Labels</td><td><code>mdi:label</code></td><td><code>/config/labels</code></td></tr><tr><td>States</td><td><code>mdi:list-status</code></td><td><code>/config/tools/state</code></td></tr><tr><td>Actions</td><td><code>mdi:run</code></td><td><code>/config/tools/action</code></td></tr></tbody></table></div><p><strong>Icons are editable defaults for new links.</strong> Existing links are reused by URL and retain their custom names and icons, including legacy States URLs at <code>/developer-tools/state</code>. Existing groups, colors, order and VIS/dashboard settings are not migrated or reset. <strong>Save</strong> in the Manager applies link settings; <strong>Cancel</strong> discards the open draft.</p><div class="tip custom-block"><p class="custom-block-title">Verified on .177 with HA 2026.11.0 · 8 November 2026</p><p>Following a fresh full backup, the desktop two-column layout, four new destinations, default icons, folder assignment, Cancel, Save and full reload passed. Temporary test links removed; user preferences, colors, groups, test dashboard and resources exactly match the PC backup. <strong>73 automated tests</strong> pass, including Marketplace version boundaries. Mobile layout and older HA versions were not separately live-tested.</p></div><p><img src="'+a+'" alt="Two-column Home Assistant shortcuts in Sidebar Manager 0.1.10, tested on .177; German test interface"></p><div class="info custom-block"><p class="custom-block-title">HA 2026.11: color preview fixed</p><p>Version <strong>0.1.9</strong> fixes missing text/icon colors in the native edit dialog, including group colors. Verified on .177 (port 80), Core 2026.11.0 / frontend 20261028.4: colors, opacity, Cancel, Save, theme reset and a full reload. All 72 automated tests pass. Disposable group/link removed; the exported layout again matches the pre-test backup. Existing settings and “Test für APP” are preserved.</p></div><p><a href="/en/collection/ha-2026-11-compatibility">Scope, results and remaining findings</a>.</p><img src="'+o+`" width="80" height="80" alt="Sidebar Manager"><p><strong>0.1.11 · Home Assistant ≥ 2026.10.3 · DE / EN / FR · MIT</strong></p><p>Organize Home Assistant&#39;s sidebar with folders, colors, opacity and custom links, directly from <strong>Edit sidebar</strong>. Move main entries and folders with the native drag handles. No HA core files are replaced.</p><p><a href="https://github.com/rockbaer2007/ha-sidebar-manager" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://github.com/rockbaer2007/ha-sidebar-manager/releases/tag/v0.1.11" target="_blank" rel="noreferrer">Release 0.1.11</a> · <a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=ha-sidebar-manager&amp;category=plugin" target="_blank" rel="noreferrer">HACS</a></p><h2 id="new-in-0-1-8-links-in-the-sidebar-editor" tabindex="-1">New in 0.1.8: links in the sidebar editor <a class="header-anchor" href="#new-in-0-1-8-links-in-the-sidebar-editor" aria-label="Permalink to &quot;New in 0.1.8: links in the sidebar editor&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Verification status, 2 November 2026</p><p><strong>0.1.8: successful functional verification confirmed by the user on 2 November 2026.</strong> Links, colors, moving entries and the Link/Ext. link labels work. Syntax checks, the build and <strong>70 automated tests</strong> also pass. Existing screenshots show earlier verification stages. Codex did not perform an additional independent HA runtime test for this release; the user’s test host and HA version were not separately specified.</p></div><p>Custom internal and external links now also appear in <strong>Edit sidebar</strong>. Links without a saved position initially appear at the end; existing ordering is respected. Hidden links remain available for editing.</p><ul><li><strong>Color field:</strong> the same color/opacity picker used for HA entries. <strong>Theme color</strong> removes the override. Saved link colors apply immediately when sidebar rows are created.</li><li><strong>Link type:</strong> the settings button displays <strong>Link</strong> for internal targets and <strong>Ext. link</strong> for external HTTP(S) targets, instead of the folder name. Clicking opens that link’s settings. Its folder assignment is preserved and also shown in the tooltip.</li><li><strong>Drag handle:</strong> reorder links alongside other entries, including within their assigned folder. Dragging alone does not change folder membership; choose the folder in the link settings. Keyboard sorting remains available.</li><li><strong>Eye:</strong> hide or show a link without deleting it or its settings.</li><li><strong>Save/Cancel:</strong> apply or discard color, visibility and order changes in the HA editing dialog. General link settings are still saved in the Manager.</li></ul><p>Link ordering and visibility remain in <code>ugso_sidebar_manager_v1</code>; colors stay in the existing <code>ugso_sidebar_colors_v1</code> record. Custom link IDs never enter HA’s native saved panel order. Existing settings, opening modes and missing panels are preserved.</p><p>Local checks exercise the built JavaScript package with simulated HA storage, DE/EN/FR labels, color selection, Save/Cancel, sorting, preserved folder membership and recovery after a failed save. The user confirmed successful functional verification on 2 November 2026; this acceptance is recorded separately from the automated tests.</p><h2 id="install-with-hacs-marketplace" tabindex="-1">Install with HACS / Marketplace <a class="header-anchor" href="#install-with-hacs-marketplace" aria-label="Permalink to &quot;Install with HACS / Marketplace&quot;">​</a></h2><p>This is a frontend plugin, not a Supervisor app or a dashboard card. Add <code>https://github.com/rockbaer2007/ha-sidebar-manager</code> as a custom repository in HACS, category <strong>Dashboard</strong> (<code>plugin</code> internally), and download Sidebar Manager. A public repository is not automatically included in the default catalog. The package uses a HACS-compatible structure for Marketplace.</p><div class="tip custom-block"><p class="custom-block-title">Marketplace installation confirmed</p><p>On <strong>5 November 2026</strong>, the user confirmed successful installation through <strong>Marketplace</strong>. This supplements the documented Sidebar Manager 0.1.9 checks. The exact Marketplace version was not separately specified; this does not certify every version.</p></div><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=ha-sidebar-manager&amp;category=plugin" target="_blank" rel="noreferrer">Open in HACS</a></p><p>Back up HA first. Merge this into the <strong>existing</strong> <code>frontend:</code> section of <code>configuration.yaml</code>, keeping themes and other modules:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  extra_module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/hacsfiles/ha-sidebar-manager/ha-sidebar-manager.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Remove or disable the old Sidebar Colors and Sidebar Organizer module entries; load only Sidebar Manager. Check the configuration, restart HA and reload the browser. A dashboard resource alone does not load the extension reliably when another HA page is opened first.</p><h2 id="manual-installation" tabindex="-1">Manual installation <a class="header-anchor" href="#manual-installation" aria-label="Permalink to &quot;Manual installation&quot;">​</a></h2><p>Download <code>ha-sidebar-manager.js</code> from Releases and copy it to <code>/config/www/ha-sidebar-manager/ha-sidebar-manager.js</code>. Use this module URL instead:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  extra_module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/local/ha-sidebar-manager/ha-sidebar-manager.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Do not load the manual and HACS copies together. The ZIP includes the same bundle, configuration examples, license and DE/EN/FR instructions. Existing versioned local installations such as <code>/local/ugso-sidebar-manager/0.1.7/ha-sidebar-manager.js</code> can keep that path if the matching file is present. For updates, retain your chosen path and reload the browser.</p><h2 id="websites-inside-ha" tabindex="-1">Websites inside HA <a class="header-anchor" href="#websites-inside-ha" aria-label="Permalink to &quot;Websites inside HA&quot;">​</a></h2><p>New-tab links work without additional configuration. For <strong>Display on the right (iframe)</strong>, also merge this entry into <code>configuration.yaml</code> or its existing <code>panel_custom</code> list:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">panel_custom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ugso-sidebar-web</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    url_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ugso-sidebar-web</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/hacsfiles/ha-sidebar-manager/ha-sidebar-manager.js</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    embed_iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    require_admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>For manual installation, change <code>module_url</code> to <code>/local/ha-sidebar-manager/ha-sidebar-manager.js</code>. It must match your frontend module URL. Validate and restart HA. No <code>sidebar_title</code> is set: this registers a hidden host panel, not another menu entry. See <code>panel-custom.example.yaml</code> and <code>panel-custom.manual.example.yaml</code> in the release ZIP.</p><p>The target website must allow embedding. CSP/X-Frame-Options, HTTPS-to-HTTP restrictions or the website&#39;s own login can prevent display. A new-tab alternative remains available. No HA token is passed to the website. Registering the host panel does not change permissions on HA&#39;s destination pages.</p><h2 id="use" tabindex="-1">Use <a class="header-anchor" href="#use" aria-label="Permalink to &quot;Use&quot;">​</a></h2><p>Hold the sidebar heading to open <strong>Edit sidebar</strong>. Color fields, eye buttons and the native drag handles remain available. <strong>Manage groups and links</strong> opens the Manager. The interface follows your HA language: German, English or French, with English fallback.</p><ul><li>Choose entry colors and opacity; <strong>Theme color</strong> clears an override. The checkerboard indicates transparency.</li><li>Create folders with names, MDI icons, colors and initial expanded/collapsed state. Assign existing main-menu entries or custom links to folders; choose <strong>Main menu</strong> to move them back.</li><li>Drag folders between main entries in the native editor. Group membership is preserved: the folder and its children move together. Keyboard sorting is also available (Alt+Up/Down on a row).</li><li>Bottom-pinned folders also appear at the bottom in the editor. Moving one before a normal menu block releases its bottom pin; Cancel preserves the original pin and position.</li><li>Set the folder separator to <strong>0–4 px</strong>. Zero means off. It appears only while the group is expanded, at the end of the block, in the icon&#39;s color/opacity, with 1 px spacing above and below.</li><li>Add Logs, Automations, Entities, Labels, States and Actions with a selectable folder; Marketplace is additionally available from HA 2026.11.0. Matching existing links are reused; names and MDI icons remain editable.</li><li>Own internal links are pale yellow in settings; external HTTP(S) links are light blue. Choose a new tab or iframe for external links. Older links retain their previous same-window behavior until edited. These settings highlights do not replace custom sidebar colors.</li><li>The Manager&#39;s <strong>Save</strong> commits its layout. Color/native order edits in the underlying HA dialog require that dialog&#39;s <strong>Save</strong>. Cancel discards the respective open draft.</li></ul><p>Settings, profile and notifications remain native. Hiding an entry or changing its group does not grant or restrict access.</p><h2 id="screenshots-and-verification" tabindex="-1">Screenshots and verification <a class="header-anchor" href="#screenshots-and-verification" aria-label="Permalink to &quot;Screenshots and verification&quot;">​</a></h2><p>Color picker and group settings:</p><p><img src="`+s+'" alt="Color picker"></p><p><img src="'+t+'" alt="Folder settings"></p><p>Actual 0.1.7 folder placement and collapsed separator on the authorized .177 test system:</p><p><img src="'+i+'" alt="Saved folder position"></p><p><img src="'+n+'" alt="Collapsed folder without separator"></p><p><img src="'+r+'" alt="Website on the right inside HA"></p><p>0.1.7 was verified on HA <strong>2026.10.4</strong>, port 80: Save/Cancel, moving a bottom-pinned test folder, browser reload, folder membership and expanded-only separators. Earlier tests cover colors, opacity, custom links, iframe/new-tab opening and layout export/import. Existing settings and the protected test dashboard were preserved; temporary test objects were removed. <strong>60 automated tests pass.</strong> The color/link screenshots also illustrate unchanged functionality from 0.1.6. <a href="https://github.com/rockbaer2007/ha-sidebar-manager/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Detailed test history</a>.</p><p>HA 2026.10.3 is the intended minimum, not a separate live-tested installation. No live compatibility claim is made for every external website or Marketplace version.</p><h2 id="preserve-settings-and-switch-safely" tabindex="-1">Preserve settings and switch safely <a class="header-anchor" href="#preserve-settings-and-switch-safely" aria-label="Permalink to &quot;Preserve settings and switch safely&quot;">​</a></h2><ol><li>Create a full HA backup. Export existing Organizer settings and Manager/color backups where available.</li><li>Disable the previous sidebar module entries without deleting their files or user settings. Install only one Sidebar Manager copy.</li><li>Existing Sidebar Colors data stays under <code>ugso_sidebar_colors_v1</code>. Manager layouts stay under <code>ugso_sidebar_manager_v1</code>, per authenticated HA user and synchronized between clients.</li><li>Organizer YAML/layout import is <strong>not implemented</strong>. Keep its export and recreate the desired folders/links manually. No automatic Organizer migration is claimed.</li></ol><p>Missing panels remain stored. Read failures and unsupported schemas never write defaults. Before writes, the previous layout is saved in local browser storage; blocked storage prevents saving. Concurrent edits are checked before writes; uncertain confirmations are read back rather than blindly retried. This is not an atomic server-side compare-and-swap.</p><p>Manager JSON export/import covers folders, links, labels, icons, visibility, pinning, order and separator settings, not access tokens or native HA preferences. Entry colors keep their separate backup. Reset affects the open Manager draft until saved. To roll back, restore the previous module entry, restart HA and reload the browser; leave stored user settings intact.</p><h2 id="development-and-scope" tabindex="-1">Development and scope <a class="header-anchor" href="#development-and-scope" aria-label="Permalink to &quot;Development and scope&quot;">​</a></h2><p>Node 22 or newer: <code>npm ci</code>, <code>npm run check</code>, <code>npm run build</code>, <code>npm test</code>. Tagged releases build the self-contained JS and installable ZIP automatically.</p><p>Native sidebar internals can change with HA frontend updates. No per-device layouts, arbitrary CSS/templates, automatic Organizer migration or configurable header/width are included. Pinned items remain within the scrollable main navigation.</p><p>Original UGSo implementation based on Sidebar Colors. <a href="https://github.com/ngocjohn/sidebar-organizer" target="_blank" rel="noreferrer">Sidebar Organizer by Viet Ngoc</a> is a behavioral reference; no Organizer source is embedded. MIT license: see <a href="https://github.com/rockbaer2007/ha-sidebar-manager/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a>.</p>',61)])])}const A=l(h,[["render",g]]);export{E as __pageData,A as default};
